<template><div class="diagnosis"><h1>Hier14 故障诊断</h1><p>上传包含 Time 及模型所需传感器列的 CSV 文件，执行 14 类故障诊断。</p><el-card><input type="file" accept=".csv" @change="file=$event.target.files[0]"/><el-button type="primary" :loading="loading" :disabled="!file" @click="submit">开始诊断</el-button><el-alert v-if="error" :title="error" type="error"/><div v-if="result" class="result"><el-descriptions :column="2" border><el-descriptions-item label="当前诊断">{{result.pred_name}}</el-descriptions-item><el-descriptions-item label="置信度">{{result.class_probs?.[0]?.prob}}</el-descriptions-item><el-descriptions-item label="窗口数">{{result.n_windows}}</el-descriptions-item><el-descriptions-item label="模型">Hier14</el-descriptions-item></el-descriptions><pre>{{JSON.stringify(result,null,2)}}</pre></div></el-card></div></template>
<script setup>import{ref}from'vue';import{ElMessage}from'element-plus';const file=ref(null),loading=ref(false),result=ref(null),error=ref('');async function submit(){loading.value=true;error.value='';const fd=new FormData();fd.append('file',file.value);try{const r=await fetch('/api/v1/fault-diagnosis/predict/',{method:'POST',body:fd,credentials:'include'}),d=await r.json();if(!r.ok)throw Error(d.error||'诊断失败');result.value=d.result}catch(e){error.value=e.message;ElMessage.error(e.message)}finally{loading.value=false}}</script><style scoped>.diagnosis{padding:24px;max-width:1100px}.diagnosis h1{margin-bottom:8px}.el-button{margin-left:12px}.el-alert{margin-top:16px}.result{margin-top:20px}pre{white-space:pre-wrap;background:#f6f8fa;padding:12px}</style>
